(function () {
  'use strict';
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const statusLabel = {RASCUNHO:'Rascunho',PENDENTE_APROVACAO:'Aguardando aprovação',APROVADO:'Aprovada',EM_ATENDIMENTO:'Em atendimento',CONCLUIDO:'Concluída',REJEITADO:'Rejeitada',CANCELADO:'Cancelada'};
  const serviceLabel = {viagem:'Viagens',viagens:'Viagens',mobilidade:'Mobilidade',entregas:'Entregas',estacionamento:'Estacionamento',correios:'Correios',xerox:'Xerox / Impressões',achados_perdidos:'Achados e Perdidos',liberacao_acesso:'Acessos',autorizacao_excepcional:'Autorizações Excepcionais',transporte:'Transportes'};
  const empty = message => `<div class="admin-empty">${esc(message)}</div>`;
  const fmtDate = value => value ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(value)) : 'Data não informada';
  const initialData = () => window.CS360_INITIAL_MOCK || window.CS360_MOCK_DATA || {};
  const getMock = () => initialData().dashboard || {};

  function normalizeRequests(list) { return Array.isArray(list) ? list : []; }
  function distributionFrom(requests) { return requests.reduce((result, request) => { result[request.status] = (result[request.status] || 0) + 1; return result; }, {}); }
  function inPeriod(request, days) { if (!request.createdAt) return true; return Date.now()-new Date(request.createdAt).getTime() <= days*86400000; }
  function renderDaily(requests, days, mock) {
    const el=$('admin-daily-chart'); if(!el) return;
    const dated=requests.filter(r=>r.createdAt);
    let labels=[], values=[];
    if(dated.length){ for(let i=Math.min(days,7)-1;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i); labels.push(d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})); values.push(dated.filter(r=>new Date(r.createdAt).toDateString()===d.toDateString()).length);}}
    else { const src=days===30?mock.solicitacoesPor30Dias:mock.solicitacoesPorDia; labels=src?.days||[]; values=src?.values||[]; }
    if(!values.length){el.innerHTML=empty('Nenhuma solicitação no período.');return;}
    const max=Math.max(...values,1); el.innerHTML=`<div class="admin-line-bars">${values.map((v,i)=>`<div class="admin-line-column" title="${esc(labels[i])}: ${v}"><span style="height:${Math.max(4,v/max*100)}%"></span><small>${esc(labels[i])}</small></div>`).join('')}</div>`;
  }
  function renderExpenses(mock, days){const el=$('admin-expense-chart');const rows=days===30?(mock.gastosPorCategoriaTrimestre||mock.gastosPorCategoria):mock.gastosPorCategoria;if(!rows?.length){el.innerHTML=empty('Sem dados de gastos para o período.');return;}const max=Math.max(...rows.map(x=>x.value),1);el.innerHTML=`<div class="admin-expense-bars">${rows.map(x=>`<a href="financeiro.html" class="admin-expense-row"><span>${esc(x.name)}</span><i><b style="width:${x.value/max*100}%;background:${esc(x.color)}"></b></i><strong>${new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(x.value)} <small>demo</small></strong></a>`).join('')}</div>`;}
  function renderStatus(distribution){const el=$('admin-status-list');const groups=[['CONCLUIDO','Concluídas'],['EM_ATENDIMENTO','Em atendimento'],['PENDENTE_APROVACAO','Aguardando aprovação'],['OTHER','Pendentes / outros']];const known=['CONCLUIDO','EM_ATENDIMENTO','PENDENTE_APROVACAO'];const total=Object.values(distribution).reduce((a,b)=>a+Number(b||0),0);if(!total){el.innerHTML=empty('Nenhuma solicitação no período.');return;}el.innerHTML=groups.map(([key,label])=>{const count=key==='OTHER'?Object.entries(distribution).filter(([k])=>!known.includes(k)).reduce((a,[,v])=>a+Number(v||0),0):Number(distribution[key]||0);const query=key==='OTHER'?'':'?status='+key;return `<a href="solicitacoes.html${query}" class="admin-status-item"><span>${label}</span><strong>${count}</strong><small>${Math.round(count/total*100)}%</small></a>`}).join('');}
  function renderQueue(requests){const el=$('admin-queue-summary');const counts={RASCUNHO:0,APROVADO:0,EM_ATENDIMENTO:0,ATRASADO:0};requests.forEach(r=>{if(r.status==='RASCUNHO')counts.RASCUNHO++;if(r.status==='APROVADO')counts.APROVADO++;if(r.status==='EM_ATENDIMENTO')counts.EM_ATENDIMENTO++;if(r.dueAt&&new Date(r.dueAt)<new Date()&&!['CONCLUIDO','CANCELADO','REJEITADO'].includes(r.status))counts.ATRASADO++;});const items=[['Novas',counts.RASCUNHO,'status=RASCUNHO'],['Em triagem',counts.APROVADO,'status=APROVADO'],['Em atendimento',counts.EM_ATENDIMENTO,'status=EM_ATENDIMENTO'],['Atrasadas',counts.ATRASADO,'overdue=true']];if(!requests.length){el.innerHTML=empty('Sem itens pendentes na fila.');return;}el.innerHTML=items.map(([label,count,q])=>`<a href="solicitacoes.html?${q}"><span>${label}</span><strong>${count}</strong><span>→</span></a>`).join('');}
  function renderRecent(requests){const body=$('admin-recent-body'), no=$('admin-recent-empty');const rows=[...requests].sort((a,b)=>new Date(b.updatedAt||b.createdAt||0)-new Date(a.updatedAt||a.createdAt||0)).slice(0,5);body.innerHTML='';no.hidden=!!rows.length;if(!rows.length)return;body.innerHTML=rows.map(r=>`<tr tabindex="0" data-href="solicitacao-detalhe.html?id=${encodeURIComponent(r.id)}"><td>${esc(r.requesterName||'Solicitante não informado')}</td><td>${esc(serviceLabel[r.serviceType]||r.serviceType||r.title||'Serviço')}</td><td><span class="status-badge status-${esc(r.status)}">${esc(statusLabel[r.status]||r.status)}</span></td><td>${esc(r.costCenter||r.employeeProfile?.costCenter||'CC não informado')}</td><td>${esc(fmtDate(r.updatedAt||r.createdAt))}</td><td>→</td></tr>`).join('');body.querySelectorAll('tr').forEach(row=>{const go=()=>location.href=row.dataset.href;row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}});});}
  function renderOperations(requests){const count=s=>requests.filter(r=>r.serviceType===s).length;$('admin-mail-posts').textContent=count('correios');$('admin-mail-prints').textContent=count('xerox');$('admin-mail-tracking').textContent=requests.filter(r=>r.serviceType==='correios'&&r.status==='EM_ATENDIMENTO').length;const rides=initialData().mobilityRides||[];const state=$('admin-mobility-summary');if(!rides.length){state.textContent='Dados de conformidade ainda não disponíveis.';return;}const exceptions=rides.filter(r=>r.policyFlag).length;state.innerHTML=`<strong>${Math.round((rides.length-exceptions)/rides.length*100)}%</strong><span>Conformidade demonstrativa · ${rides.length-exceptions} conformes · ${exceptions} exceções</span>`;}
  function setKpis(requests, distribution, mock, days){const period=requests.filter(r=>inPeriod(r,days));$('admin-kpi-total').textContent=period.length;$('admin-kpi-progress').textContent=distribution.EM_ATENDIMENTO||0;$('admin-kpi-approval').textContent=distribution.PENDENTE_APROVACAO||0;const overdue=requests.filter(r=>r.dueAt&&new Date(r.dueAt)<new Date()&&!['CONCLUIDO','CANCELADO','REJEITADO'].includes(r.status)).length;$('admin-kpi-overdue').textContent=overdue;$('admin-kpi-critical').textContent=overdue+(distribution.PENDENTE_APROVACAO||0);const saving=mock.kpis?.economiaMes?.value;$('admin-kpi-savings').textContent=saving?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',notation:'compact'}).format(saving):'Indisponível';}
  async function load(){const mock=getMock();let requests=[],distribution={};try{const [req,dist]=await Promise.all([CS360API.getRequests(),CS360API.getStatusDistribution()]);requests=normalizeRequests(req.data);distribution=dist.data||{};}catch(error){console.warn('[Admin Dashboard] API indisponível; exibindo agregados demonstrativos centralizados.',error);requests=normalizeRequests(initialData().requests);const s=mock.statusSolicitacoes?.segments||[];distribution={CONCLUIDO:s.find(x=>x.label?.includes('Conclu'))?.count||0,EM_ATENDIMENTO:s.find(x=>x.label?.includes('atendimento'))?.count||0,PENDENTE_APROVACAO:s.find(x=>x.label?.includes('aprova'))?.count||0};}const render=()=>{const days=Number($('admin-period').value);const periodRequests=requests.filter(r=>inPeriod(r,days));const periodDistribution=periodRequests.length?distributionFrom(periodRequests):distribution;setKpis(requests,periodDistribution,mock,days);renderDaily(requests,days,mock);renderExpenses(mock,days);renderStatus(periodDistribution);renderQueue(requests);renderRecent(requests);renderOperations(requests);};render();$('admin-period').addEventListener('change',render);}
  function assistant(){const drawer=$('role-context-assistant'),backdrop=$('admin-assistant-backdrop'),trigger=$('admin-assistant-trigger');const toggle=open=>{drawer.classList.toggle('is-open',open);drawer.setAttribute('aria-hidden',String(!open));trigger.setAttribute('aria-expanded',String(open));backdrop.hidden=!open;if(open)$('admin-assistant-input').focus();};trigger.addEventListener('click',()=>toggle(true));$('admin-assistant-close').addEventListener('click',()=>toggle(false));backdrop.addEventListener('click',()=>toggle(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false);});$('admin-assistant-form').addEventListener('submit',e=>{e.preventDefault();const input=$('admin-assistant-input');if(!input.value.trim())return;document.querySelector('.admin-assistant-content').insertAdjacentHTML('beforeend',`<p class="admin-assistant-question"><strong>Você:</strong> ${esc(input.value)}</p><div class="alert-box alert-info">Não encontrei uma orientação institucional cadastrada para este caso. Consulte a política oficial ou a Central de Serviços.</div>`);input.value='';});}
  document.addEventListener('DOMContentLoaded',()=>{load();assistant();});
})();
